css:
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--txt);font:var(--w-normal) var(--fs)/var(--lh) var(--font)}.wrap{max-width:1180px;margin:0 auto;padding:18px 14px 40px}
header{border-bottom:1px solid var(--line);padding-bottom:10px;margin-bottom:12px}.caps{font:var(--w-normal) var(--fs-note)/1.4 var(--mono);letter-spacing:.08em;color:var(--dim);text-transform:uppercase}
h1{font:var(--w-bold) var(--fs-title)/1.25 var(--serif);margin:4px 0 6px}h2{font:var(--w-bold) var(--fs-h)/1.3 var(--font);margin:0 0 6px}.note{font-size:var(--fs-note);color:var(--dim)}.mono{font-family:var(--mono)}
.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:10px 10px 8px;margin:0 0 10px}
.verdict{display:flex;flex-wrap:wrap;gap:8px 12px;align-items:center;background:var(--sys-bg);border:1px solid var(--line);border-left:4px solid var(--seal);border-radius:var(--radius);padding:8px 10px;margin:0 0 10px}
.verdict b{font:var(--w-bold) var(--fs-h)/1.2 var(--font);color:var(--seal)}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:var(--fs)}
th,td{border-bottom:1px solid var(--hair);padding:5px var(--pad);text-align:left;vertical-align:top;overflow-wrap:anywhere}
th{font:var(--w-bold) var(--fs-note)/1.3 var(--font);color:var(--dim);background:var(--chip);border-bottom:1px solid var(--line);white-space:nowrap}
tbody tr:nth-child(even) td{background:var(--zebra)}td.l,th.l{width:44px;white-space:nowrap}td.k{white-space:nowrap;font-weight:var(--w-bold)}td.n{white-space:nowrap}
.lamp{display:inline-block;min-width:30px;padding:1px 7px;border-radius:999px;font:var(--w-bold) var(--fs-note)/1.5 var(--font);color:var(--panel);text-align:center}
.g{background:var(--lamp-green)}.y{background:var(--lamp-yellow)}.r{background:var(--lamp-red);animation:bl 2.4s ease-in-out infinite}.x{background:var(--lamp-gray)}
@keyframes bl{0%,100%{opacity:1}50%{opacity:.35}}@media (prefers-reduced-motion:reduce){.r{animation:none}}
.nav{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0 0}.nav a{font:500 var(--fs-note)/1 var(--mono);color:var(--txt);text-decoration:none;border:1px solid var(--line);border-radius:999px;padding:5px 9px;background:var(--panel)}
.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(132px,1fr));gap:8px;margin:0 0 10px}
.kc{display:flex;flex-direction:column;gap:2px;text-align:left;background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:8px 10px;font:inherit;color:inherit;cursor:pointer;min-width:0}
.kc:hover,.kc:focus-visible{border-color:var(--txt);outline:none}.kc[aria-pressed="true"]{border-color:var(--seal);box-shadow:inset 0 0 0 1px var(--seal)}
.kc .kn{font:var(--w-bold) var(--fs-title)/1.1 var(--serif);font-variant-numeric:tabular-nums}.kc .kl{font:var(--w-bold) var(--fs)/1.3 var(--font);display:flex;gap:6px;align-items:center}
.kc .kr{font-size:var(--fs-note);color:var(--dim);overflow-wrap:anywhere}
.bar{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:end;margin:6px 0 8px}.bar label{display:flex;flex-direction:column;gap:2px;font:var(--w-bold) var(--fs-note)/1.2 var(--font);color:var(--dim)}
.bar select,.bar input,.bar button{font:var(--w-normal) var(--fs)/1.2 var(--font);padding:5px 7px;border:1px solid var(--line);border-radius:6px;background:var(--panel);color:var(--txt);min-width:110px}.bar input{min-width:200px}.bar button{cursor:pointer;min-width:0}
.box{max-height:560px;overflow:auto;border:1px solid var(--hair);border-radius:6px}.box thead th{position:sticky;top:0;z-index:1}.num{font-variant-numeric:tabular-nums}
.pack{margin:6px 0 0;padding:8px 10px;max-height:420px;overflow:auto;background:var(--chip);border:1px solid var(--hair);border-radius:6px;font:var(--w-normal) var(--fs-note)/1.55 var(--mono);white-space:pre-wrap;overflow-wrap:anywhere}
@media (max-width:640px){.wrap{padding:12px 8px 30px}.cards{grid-template-columns:repeat(auto-fill,minmax(104px,1fr))}}
